import{_ as a,o as t,c as n,ap as i,bb as r,bc as s,bd as o,be as l}from"./chunks/framework.BumGKp4W.js";const b=JSON.parse('{"title":"Credential Management","description":"","frontmatter":{"permalink":"/docs/usage/common/credential-management/"},"headers":[],"relativePath":"docs/usage/common/credential-management.md","filePath":"docs/usage/common/credential-management.md"}'),c={name:"docs/usage/common/credential-management.md"};function d(h,e,p,m,g,u){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="credential-management" tabindex="-1">Credential Management <a class="header-anchor" href="#credential-management" aria-label="Permalink to “Credential Management”">​</a></h1><p>This page describes the concept behind credential management in SLM and how to use it via the UI. The credential management provides a consistent way to:</p><ul><li>store sensitive authentication data securely</li><li>represent credential metadata in a domain model</li><li>assign credentials to technical entities (for example resources or services)</li><li>control usage via scopes</li></ul><p>The goal is to keep secret handling centralized while allowing multiple components to reuse credentials in a controlled way. The central credential management is done via Platform Management, while for the actual secret storage, Vault is used as a secure backend.</p><h2 id="concept" tabindex="-1">Concept <a class="header-anchor" href="#concept" aria-label="Permalink to “Concept”">​</a></h2><h3 id="core-model" tabindex="-1">Core model <a class="header-anchor" href="#core-model" aria-label="Permalink to “Core model”">​</a></h3><p>The model is centered around the <code>Credential</code> aggregate and three dimensions:</p><ul><li><strong>Credential:</strong> What the credential is (metadata and reference to secret data)</li><li><strong>Credential Data:</strong> What the credential contains</li><li><strong>Credential Entity Links:</strong> Where the credential is used</li></ul><p><code>Credential</code> is the main object and contains an identifier, name, scopes, and a reference to the <code>Credential Data</code> (secret payload). The <code>Credential Data</code> is polymorphic and can represent different types of credentials (for example username/password or key pairs). A <code>Credential Entity Link</code> connects one credential to one domain entity. A credential can have multiple links and therefore be reused across multiple entities if allowed by scope and business rules. A credential is considered as orphaned when no relevant business links remain. In SLM-specific rules, this may be further constrained (for example by remaining link types or non-empty scopes).</p><h3 id="separation-of-concerns" tabindex="-1">Separation of concerns <a class="header-anchor" href="#separation-of-concerns" aria-label="Permalink to “Separation of concerns”">​</a></h3><p>The concept separates responsibilities into three layers:</p><ul><li><strong>Metadata layer</strong>: Credential, links, scopes, names</li><li><strong>Secret payload layer</strong>: concrete credential data values</li><li><strong>Security/storage layer</strong>: secret persistence and access control</li></ul><p>According to the model note, secret payload is stored in a Vault KV secret engine. The domain model references this data but does not expose internal Vault structure.</p><h3 id="security-principles" tabindex="-1">Security principles <a class="header-anchor" href="#security-principles" aria-label="Permalink to “Security principles”">​</a></h3><p>Credential Management follows these principles:</p><ul><li><strong>Least privilege</strong> through scopes</li><li><strong>Explicit ownership and linkage</strong> through entity links</li><li><strong>Strict type safety</strong> through different credential data types</li><li><strong>No secret duplication</strong> across entities</li><li><strong>Centralized secret storage</strong> in Vault</li></ul><p>Operationally, secret read access is stricter than metadata access.</p><h2 id="usage-in-ui" tabindex="-1">Usage in UI <a class="header-anchor" href="#usage-in-ui" aria-label="Permalink to “Usage in UI”">​</a></h2><p>The UI provides a centralized credentials section in the user profile. It allows users to search and filter credentials by scope, inspect metadata and view non-sensitive credential details in a structured way. <img src="'+r+'" alt="User credentials overview" data-zoomable="true"></p><h3 id="create-credential" tabindex="-1">Create credential <a class="header-anchor" href="#create-credential" aria-label="Permalink to “Create credential”">​</a></h3><p>New credentials can be created directly from the credentials section. The dialog guides the user through selecting the credential type and entering the required fields (for example username and password) together with a descriptive credential name. Credentials can be also created in the context of a specific entity (e.g., when creating remote access for a resource) and then linked to that entity immediately after creation. <img src="'+s+'" alt="Create credential dialog" data-zoomable="true"></p><h3 id="use-credentials" tabindex="-1">Use credentials <a class="header-anchor" href="#use-credentials" aria-label="Permalink to “Use credentials”">​</a></h3><p>A Credential can be used in any entity that requires credentials (e.g., credentials for remote access to a resource). When using a credential, the user can either select an existing credential or create a new one. In this example, an existing credential is selected and immediately shown in the credential preview area (including non-sensitive metadata). <img src="'+o+'" alt="Select credential type for remote access" data-zoomable="true"></p><p>After confirmation, the selected credential is linked to the created remote access configuration of the device. This enables reuse of managed credentials without duplicating secret data. <img src="'+l+'" alt="Use existing credential for remote access" data-zoomable="true"></p>',24)])])}const y=a(c,[["render",d]]);export{b as __pageData,y as default};
